package com.mahaesuvidha.chandrapanchangalarm.alarm
import android.app.*;import android.content.*;import androidx.core.app.NotificationCompat
class AlarmReceiver:BroadcastReceiver(){override fun onReceive(c:Context,i:Intent){val m=c.getSystemService(NotificationManager::class.java);val ch="astro_changes";m.createNotificationChannel(NotificationChannel(ch,"चंद्र सूर्य बदल",NotificationManager.IMPORTANCE_HIGH));val n=NotificationCompat.Builder(c,ch).setSmallIcon(android.R.drawable.ic_lock_idle_alarm).setContentTitle(i.getStringExtra("title")?:"चंद्र सूर्य अलार्म").setContentText(i.getStringExtra("message")?:"स्थितीत बदल झाला.").setPriority(NotificationCompat.PRIORITY_HIGH).setCategory(NotificationCompat.CATEGORY_ALARM).setAutoCancel(true).build();m.notify(i.getIntExtra("id",2001),n);AlarmScheduler(c).scheduleAll()}}
